MODEL_NAME = "pa_lines_v33"
CHANNELS = ("seg", "cos2", "sin2", "deep", "wread")
N_OUT = 5
CPU_SMOKE = MODE == "cpusmoke"
EARLY_EPOCHS = (1, 2, 4, 8, 12, 16, 20, 24)  # epochs whose per-image validation readout is saved
