def find_apo_pairs() -> list[tuple[str, str]]:
    return find_pairs(find_dir("apo_images_new_model_v1"), find_dir("apo_masks_new_model_v1"))


def deep_edge_points(mask: np.ndarray, ref_width: float):
    """Inner (upper) edge of the deep aponeurosis band as (K,2) x,y points, or None.

    Bands are sorted top to bottom; the deep band is the first one clearly below the
    superficial band (same rule as kaggle/apo_v2 superficial_pair).
    """
    n, lab, stats, _ = cv2.connectedComponentsWithStats(mask.astype(np.uint8), connectivity=8)
    comps = []
    for k in range(1, n):
        x, y, ww, hh, area = stats[k]
        if ww < max(8, 0.15 * ref_width) or area < 30:
            continue
        sub = lab[y:y + hh, x:x + ww] == k
        present = sub.any(axis=0)
        top = sub.argmax(axis=0).astype(np.float32) + y
        bot = (hh - 1 - sub[::-1].argmax(axis=0)).astype(np.float32) + y
        comps.append({"x": int(x), "present": present, "top": top, "bot": bot,
                      "yc": float(np.median((top + bot)[present] / 2)), "width": int(present.sum())})
    comps.sort(key=lambda c: c["yc"])
    if len(comps) < 2:
        return None
    sup = comps[0]
    w = mask.shape[1]
    sbot = np.full(w, np.nan, np.float32)
    sbot[sup["x"]:sup["x"] + len(sup["bot"])][sup["present"]] = sup["bot"][sup["present"]]
    for c in comps[1:]:
        ctop = np.full(w, np.nan, np.float32)
        ctop[c["x"]:c["x"] + len(c["top"])][c["present"]] = c["top"][c["present"]]
        both = ~np.isnan(sbot) & ~np.isnan(ctop)
        if both.sum() >= 0.2 * min(sup["width"], c["width"]) and float(np.median(ctop[both] - sbot[both])) > 2:
            xs = np.flatnonzero(~np.isnan(ctop))[::DEEP_STRIDE]
            return np.stack([xs.astype(np.float32), ctop[xs] - 0.5], 1)
    return None


def prep_apo(pair: tuple[str, str]) -> dict:
    image_path, mask_path = Path(pair[0]), Path(pair[1])
    img = read_gray(image_path)
    m = read_gray(mask_path)
    if m.shape != img.shape:  # masks at original resolution: plain stretch is the alignment
        m = cv2.resize(m, (img.shape[1], img.shape[0]), interpolation=cv2.INTER_LINEAR)
    mask = m > 127
    out = {"stem": "apo_" + image_path.stem, "raw_stem": image_path.stem, "name": image_path.name, "kind": "apo",
           "path": str(image_path), "ih": sha1_array(img), "H": img.shape[0], "W": img.shape[1], "empty": True,
           "segs": np.zeros((0, 4), np.float32)}
    box, kind = viewport(img, image_path.suffix.lower())
    pts = deep_edge_points(mask, box[2] - box[0])
    if pts is None or len(pts) < 8:
        return out
    x1, y1, x2, y2 = box
    inside = (pts[:, 0] >= x1) & (pts[:, 0] < x2) & (pts[:, 1] >= y1) & (pts[:, 1] < y2)
    if inside.mean() < 0.97:
        box, kind = (0, 0, img.shape[1], img.shape[0]), kind + "_lowcov"
        x1, y1, x2, y2 = box
    crop = np.ascontiguousarray(img[y1:y2, x1:x2])
    out.update(box=box, layout=kind, crop=crop, dpts_full=pts, dpts=pts - np.array([x1, y1], np.float32),
               thumb=thumbnail(crop), empty=False)
    return out


def attach_pairs(fasc_items: list[dict], apo_items: list[dict], fasc_paths: dict) -> dict:
    """Give the fascicle item of every verified both-mask pair the deep edge of its aponeurosis twin."""
    fmap = {}
    for it in fasc_items:
        for a in it["aliases"]:
            fmap[a] = it
    amap = {it["raw_stem"]: it for it in apo_items}
    st = {"listed": len(BOTH_PAIRS), "missing": 0, "low_corr": 0, "attached": 0}
    for fs, as_ in BOTH_PAIRS:
        fi, ai = fmap.get(fs), amap.get(as_)
        if fi is None or ai is None or fs not in fasc_paths:
            st["missing"] += 1
            continue
        fimg = read_gray(Path(fasc_paths[fs]))
        aimg = cv2.resize(read_gray(Path(ai["path"])), (fimg.shape[1], fimg.shape[0]), interpolation=cv2.INTER_AREA)
        a = cv2.resize(fimg, (96, 96), interpolation=cv2.INTER_AREA).astype(np.float32).ravel()
        b = cv2.resize(aimg, (96, 96), interpolation=cv2.INTER_AREA).astype(np.float32).ravel()
        a -= a.mean()
        b -= b.mean()
        corr = float(a @ b / (np.linalg.norm(a) * np.linalg.norm(b) + 1e-6))
        if corr < PAIR_MIN_CORR or "dpts" in fi:
            st["low_corr"] += 1
            continue
        sx, sy = fimg.shape[1] / ai["W"], fimg.shape[0] / ai["H"]
        p = ai["dpts_full"].astype(np.float64)
        p = np.stack([(p[:, 0] + 0.5) * sx - 0.5 - fi["box"][0], (p[:, 1] + 0.5) * sy - 0.5 - fi["box"][1]], 1)
        fi["dpts"] = p.astype(np.float32)
        fi["twin"] = ai["stem"]
        ai["twin"] = fi["stem"]
        st["attached"] += 1
    return st


def assign_apo_folds(fasc_items: list[dict], apo_items: list[dict]) -> dict:
    """Fascicle folds stay exactly those of fasc_orient_v1. An aponeurosis image that is a twin or a
    near duplicate of a fascicle image inherits that fold; the rest are grouped and split on their own."""
    ft = np.stack([thumbnail(it["crop"]) for it in fasc_items])
    at = np.stack([it["thumb"] for it in apo_items])
    fmap = {it["stem"]: it for it in fasc_items}
    corr = at @ ft.T
    ffold = np.array([it["fold"] for it in fasc_items])
    st = {"twin": 0, "near_dup": 0, "conflict": 0, "free": 0}
    free = []
    for i, it in enumerate(apo_items):
        hit = np.flatnonzero(corr[i] > DUP_CORR)
        if "twin" in it:
            it["fold"] = fmap[it["twin"]]["fold"]
            st["twin"] += 1
            st["conflict"] += int(len(hit) and len(set(ffold[hit]) - {it["fold"]}) > 0)
        elif len(hit):
            it["fold"] = int(ffold[hit[np.argmax(corr[i][hit])]])
            st["near_dup"] += 1
            st["conflict"] += int(len(set(ffold[hit])) > 1)
        else:
            free.append(i)
    if free:
        sub = at[free]
        ii, jj = np.nonzero(np.triu(sub @ sub.T > DUP_CORR, 1))
        groups = union_find_groups(len(free), np.stack([ii, jj], 1))
        folds = assign_folds(groups, SEED + 1)
        for k, i in enumerate(free):
            apo_items[i]["fold"] = int(folds[k])
    st["free"] = len(free)
    for it in apo_items:
        del it["thumb"]
    return st


# ----------------------------------------------------------------------------- samples
def _line_angle_np(p: np.ndarray) -> float:
    q = p - p.mean(0)
    sxx, syy, sxy = float((q[:, 0] ** 2).sum()), float((q[:, 1] ** 2).sum()), float((q[:, 0] * q[:, 1]).sum())
    return 0.5 * math.atan2(2 * sxy, sxx - syy)


def make_sample(it: dict, rng: np.random.Generator | None) -> dict:
    """One view. Like fasc_orient_v1.make_sample plus the deep-edge target, the two readout
    labels (fascicle angle tf, deep-line angle tl; radians, canvas frame) and the linear map lin."""
    crop, segs, dpts = it["crop"], it["segs"], it.get("dpts")
    h, w = crop.shape
    x0, y0, ww, hh = 0, 0, w, h
    if rng is not None:
        if rng.random() < 0.35:
            ww = max(32, int(round(rng.uniform(0.3, 1.0) * w)))
            x0 = int(rng.integers(0, w - ww + 1))
        if rng.random() < 0.15:
            hh = max(32, int(round(rng.uniform(0.65, 1.0) * h)))
            y0 = int(rng.integers(0, h - hh + 1))
    sub = crop[y0:y0 + hh, x0:x0 + ww]
    m = letterbox_matrix(ww, hh)
    if rng is not None:
        m = aug_matrix(rng) @ m
    img = warp_image(sub, m)
    valid = _poly_mask(m, ww, hh)

    def inside(p):
        xi, yi = np.round(p[:, 0]).astype(int), np.round(p[:, 1]).astype(int)
        ok = (xi >= 0) & (xi < SIZE) & (yi >= 0) & (yi < SIZE)
        ok[ok] = valid[yi[ok], xi[ok]] > 0
        return ok

    hf, tf = 0, 0.0
    if len(segs):
        s = segs - np.array([x0, y0, x0, y0], np.float32)
        p1 = (m[:2, :2] @ s[:, :2].T + m[:2, 2:3]).T
        p2 = (m[:2, :2] @ s[:, 2:].T + m[:2, 2:3]).T
        segs_out = np.concatenate([p1, p2], 1)
        d = p2 - p1
        ln = np.hypot(d[:, 0], d[:, 1])
        ok = inside((p1 + p2) / 2) & (ln >= 3)
        if ok.any() and ln[ok].sum() >= MIN_FASC_LEN:
            c2 = ((d[ok, 0] ** 2 - d[ok, 1] ** 2) / ln[ok]).sum()  # length-weighted doubled angle
            s2 = (2 * d[ok, 0] * d[ok, 1] / ln[ok]).sum()
            hf, tf = 1, 0.5 * math.atan2(s2, c2)
    else:
        segs_out = np.zeros((0, 4))
    tg = render_targets(segs_out, valid)
    if it["kind"] == "apo":
        hf = 0
    deep = np.zeros((SIZE, SIZE), np.uint8)
    ha, tl = 0, 0.0
    if dpts is not None and len(dpts):
        p = dpts.astype(np.float64) - np.array([x0, y0])
        p = (m[:2, :2] @ p.T + m[:2, 2:3]).T
        gap = np.abs(np.diff(dpts[:, 0])) <= 3 * DEEP_STRIDE
        for a, b, g in zip(p[:-1], p[1:], gap):
            if g and np.isfinite(a).all() and np.isfinite(b).all() and np.abs(np.r_[a, b]).max() < 50 * SIZE:
                cv2.line(deep, (int(round(a[0] * 16)), int(round(a[1] * 16))),
                         (int(round(b[0] * 16)), int(round(b[1] * 16))), 1, DEEP_WIDTH, cv2.LINE_8, 4)
        deep &= valid
        ok = inside(p)
        if ok.sum() >= 8 and np.ptp(p[ok], axis=0).max() >= MIN_LINE_SPAN:
            ha, tl = 1, _line_angle_np(p[ok])
    if rng is not None:
        img = intensity_aug(img, valid, rng)
    tg.update(img=img, valid=valid, deep=deep, hf=np.float32(hf), ha=np.float32(ha), tf=np.float32(tf),
              tl=np.float32(tl), lin=m[:2, :2].astype(np.float32), hfseg=np.float32(it["kind"] != "apo"))
    return tg


class PairSet:
    """Two independently augmented views of every item (stacked on a new axis 0)."""

    def __init__(self, items: list[dict], augment: bool, repeat: int = 1) -> None:
        self.items, self.augment, self.repeat = items, augment, repeat

    def __len__(self) -> int:
        return len(self.items) * self.repeat

    def __getitem__(self, idx: int):
        import torch

        it = self.items[idx % len(self.items)]
        seed = (torch.initial_seed() + idx * 7919) % (2**32)
        rng = np.random.default_rng(seed)
        a, b = make_sample(it, rng), make_sample(it, rng)
        return {k: torch.from_numpy(np.stack([np.asarray(a[k]), np.asarray(b[k])])) for k in a}


# ----------------------------------------------------------------------------- readout (no parameters)
def wrap_half(d, torch):
    """Difference of two undirected angles, wrapped to (-pi/2, pi/2]."""
    return 0.5 * torch.atan2(torch.sin(2 * d), torch.cos(2 * d))


def readout(cp, sp, wr, ed, valid, torch):
    """cp, sp: tanh direction maps; wr: read weight in [0,1]; ed: deep-edge probability; valid: 0/1.
    All (B,H,W) float32. Returns fascicle angle, deep-line angle (radians, undirected) and supports."""
    w = wr * valid
    c, s = (w * cp).sum((1, 2)), (w * sp).sum((1, 2))
    th_f = 0.5 * torch.atan2(s, c + 1e-6)
    q = ed * ed * valid  # squared so the diffuse background does not flatten the fit
    qs = q.sum((1, 2)).clamp_min(1e-6)
    hh, ww = cp.shape[1:]
    ys = torch.arange(hh, device=cp.device, dtype=cp.dtype).view(1, hh, 1)
    xs = torch.arange(ww, device=cp.device, dtype=cp.dtype).view(1, 1, ww)
    mx, my = (q * xs).sum((1, 2)) / qs, (q * ys).sum((1, 2)) / qs
    dx, dy = xs - mx.view(-1, 1, 1), ys - my.view(-1, 1, 1)
    sxx, syy, sxy = (q * dx * dx).sum((1, 2)) / qs, (q * dy * dy).sum((1, 2)) / qs, (q * dx * dy).sum((1, 2)) / qs
    th_l = 0.5 * torch.atan2(2 * sxy, sxx - syy + 1e-6)
    return th_f, th_l, w.sum((1, 2)), qs


def map_angle(theta, lin_from, lin_to, torch):
    """Undirected angle theta measured in view A -> the same line seen in view B (exact for affine views)."""
    L = lin_to @ torch.linalg.inv(lin_from)
    d = torch.stack([torch.cos(theta), torch.sin(theta)], 1).unsqueeze(2)
    v = (L @ d).squeeze(2)
    return torch.atan2(v[:, 1], v[:, 0])


def build_model(pretrained: bool):
    import segmentation_models_pytorch as smp

    return smp.Unet(encoder_name=ENCODER, encoder_weights="imagenet" if pretrained else None, in_channels=3,
                    classes=N_OUT, decoder_channels=(256, 128, 64, 32, 16))


def model_out(model, x, torch):
    if DEV == "cuda":
        with torch.autocast("cuda", dtype=torch.float16):
            return model(x).float()
    return model(x).float()


def split_out(out, torch):
    return (torch.sigmoid(out[:, 0]), torch.tanh(out[:, 1]), torch.tanh(out[:, 2]), torch.sigmoid(out[:, 3]),
            torch.sigmoid(out[:, 4]))


def forward_maps(model, x, torch, tta: bool):
    """prob, cos2, sin2, deep, wread (B,H,W) float32; hflip TTA flips the sin2 sign."""
    b = x.shape[0]
    xin = torch.cat([x, torch.flip(x, dims=[3])], 0) if tta else x
    out = model_out(model, xin, torch)
    p, c, s, e, w = split_out(out[:b], torch)
    if tta:
        pf, cf, sf, ef, wf = split_out(torch.flip(out[b:], dims=[3]), torch)
        p, c, s, e, w = 0.5 * (p + pf), 0.5 * (c + cf), 0.5 * (s - sf), 0.5 * (e + ef), 0.5 * (w + wf)
    return p, c, s, e, w


# =============================================================================================
# v33 overlay, part B: losses, evaluation, fold training
# =============================================================================================
def _masked_mean(v, m):
    return (v * m).sum() / m.sum().clamp_min(1.0)


def compute_losses(out, b, torch) -> dict:
    """out (2B,5,H,W) float32; b: batch dict with views A = [:B], B = [B:]."""
    F = torch.nn.functional
    seg_t, skel, om = b["seg"].float(), b["skel"].float(), b["om"].float()
    ct, st, valid = b["cos2"].float(), b["sin2"].float(), b["valid"].float()
    deep_t, hfseg, hf, ha = b["deep"].float(), b["hfseg"], b["hf"], b["ha"]
    logit = out[:, 0]
    pw = torch.tensor([POS_WEIGHT], device=out.device)
    bce = _masked_mean(F.binary_cross_entropy_with_logits(logit, seg_t, pos_weight=pw, reduction="none").mean((1, 2)), hfseg)
    p = torch.sigmoid(logit)
    dice_l = _masked_mean(1 - (2 * (p * seg_t).sum((1, 2)) + 1) / (p.sum((1, 2)) + seg_t.sum((1, 2)) + 1), hfseg)
    sk_n = skel.sum((1, 2))
    skel_l = _masked_mean(1 - (p * skel).sum((1, 2)) / sk_n.clamp_min(1.0), (sk_n > 0).float() * hfseg)
    cp, sp = torch.tanh(out[:, 1]), torch.tanh(out[:, 2])
    ori_l = (((cp - ct).abs() + (sp - st).abs()) * om).sum() / (2 * om.sum().clamp_min(1))
    dl = out[:, 3]
    e = torch.sigmoid(dl)
    deep_bce = F.binary_cross_entropy_with_logits(dl, deep_t, pos_weight=pw, reduction="none").mean((1, 2))
    deep_dice = 1 - (2 * (e * deep_t).sum((1, 2)) + 1) / (e.sum((1, 2)) + deep_t.sum((1, 2)) + 1)
    deep_l = _masked_mean(deep_bce + deep_dice, ha)
    th_f, th_l, _, _ = readout(cp, sp, torch.sigmoid(out[:, 4]), e, valid, torch)
    fa_l = _masked_mean(wrap_half(th_f - b["tf"], torch).abs(), hf)
    ln_l = _masked_mean(wrap_half(th_l - b["tl"], torch).abs(), ha)
    pa_l = _masked_mean(wrap_half((th_l - th_f) - (b["tl"] - b["tf"]), torch).abs(), hf * ha)
    n = out.shape[0] // 2
    la, lb = b["lin"][:n].float(), b["lin"][n:].float()
    cons_l = (wrap_half(map_angle(th_f[:n], la, lb, torch) - th_f[n:], torch).abs().mean()
              + wrap_half(map_angle(th_l[:n], la, lb, torch) - th_l[n:], torch).abs().mean())
    loss = (W_BCE * bce + W_DICE * dice_l + W_SKEL * skel_l + W_ORI * ori_l + W_DEEP * deep_l
            + W_FA * fa_l + W_LN * ln_l + W_PA * pa_l + W_CONS * cons_l)
    return {"loss": loss, "bce": bce, "dice_l": dice_l, "skel_l": skel_l, "ori_l": ori_l, "deep_l": deep_l,
            "fa_l": fa_l, "ln_l": ln_l, "pa_l": pa_l, "cons_l": cons_l}


LOSS_KEYS = ("loss", "bce", "dice_l", "skel_l", "ori_l", "deep_l", "fa_l", "ln_l", "pa_l", "cons_l")


def to_dev(b: dict, torch) -> dict:
    """(B,2,...) loader batch -> (2B,...) on the device, view A first."""
    return {k: v.transpose(0, 1).reshape(-1, *v.shape[2:]).to(DEV, non_blocking=True) for k, v in b.items()}


def build_val_cache(items: list[dict], torch) -> list[dict]:
    samples = [make_sample(it, None) for it in items]
    cache = []
    for i in range(0, len(samples), BATCH):
        chunk = samples[i:i + BATCH]
        cache.append({k: torch.from_numpy(np.stack([np.asarray(s[k]) for s in chunk])) for k in chunk[0]})
    return cache


def _deg(d: float) -> float:
    d = abs(d) % math.pi
    return min(d, math.pi - d) * 180.0 / math.pi


def evaluate(model, cache, torch, tta: bool = False, rows_out: list | None = None, items: list | None = None) -> dict:
    """Dense metrics as fasc_orient_v1 plus readout errors (degrees, letterboxed frame = image frame)."""
    model.eval()
    n_img, dice_sum, ang_sum, ang_n = 0, 0.0, 0.0, 0
    fa, ln, pa = [], [], []
    k = 0
    with torch.no_grad():
        for b in cache:
            b = {kk: v.to(DEV) for kk, v in b.items()}
            x = to_input(b["img"], torch)
            p, c, s, e, w = forward_maps(model, x, torch, tta)
            valid = b["valid"].float()
            th_f, th_l, wsum, qsum = readout(c, s, w, e, valid, torch)
            seg_t, m = b["seg"] > 0, (b["skel"] > 0) & (b["om"] > 0)
            d = torch.remainder(0.5 * torch.atan2(s, c) - 0.5 * torch.atan2(b["sin2"].float(), b["cos2"].float()), math.pi)
            d = torch.minimum(d, math.pi - d) * (180.0 / math.pi)
            for i in range(x.shape[0]):
                hf, ha = bool(b["hf"][i] > 0), bool(b["ha"][i] > 0)
                if bool(b["hfseg"][i] > 0):
                    n_img += 1
                    pred = p[i] > 0.5
                    den = float(pred.sum() + seg_t[i].sum())
                    dice_sum += 2 * float((pred & seg_t[i]).sum()) / den if den > 0 else 1.0
                    if int(m[i].sum()) >= 10:
                        ang_sum += float(d[i][m[i]].mean())
                        ang_n += 1
                tf, tl, pf, pl = float(b["tf"][i]), float(b["tl"][i]), float(th_f[i]), float(th_l[i])
                if hf:
                    fa.append(_deg(pf - tf))
                if ha:
                    ln.append(_deg(pl - tl))
                if hf and ha:
                    pa.append(_deg((pl - pf) - (tl - tf)))
                if rows_out is not None:
                    it = items[k]
                    rows_out.append([it["stem"], it["kind"], it.get("twin", ""), it["fold"], int(hf), int(ha),
                                     round(math.degrees(tf), 4), round(math.degrees(tl), 4),
                                     round(math.degrees(pf), 4), round(math.degrees(pl), 4),
                                     round(float(wsum[i]), 2), round(float(qsum[i]), 2)])
                k += 1
    mean = lambda v: float(np.mean(v)) if v else float("nan")  # noqa: E731
    out = {"dice50": dice_sum / max(1, n_img), "ang_mae": ang_sum / max(1, ang_n), "fa_mae": mean(fa),
           "ln_mae": mean(ln), "pa_mae": mean(pa), "n_fa": len(fa), "n_ln": len(ln), "n_pa": len(pa)}
    parts = [v for v in (out["fa_mae"], out["ln_mae"]) if v == v]
    out["score"] = float(np.mean(parts)) if parts else float("inf")  # model selection: readout errors only
    return out


OOF_COLS = ["stem", "kind", "twin", "fold", "has_fasc", "has_deep", "gt_fasc_deg", "gt_line_deg", "pred_fasc_deg",
            "pred_line_deg", "w_sum", "q_sum"]


def _smoke_pick(items: list[dict], n: int, rng) -> list[dict]:
    """Equal thirds of both-mask, fascicle-only and aponeurosis-only items."""
    pools = [[it for it in items if it["kind"] == "fasc" and "dpts" in it],
             [it for it in items if it["kind"] == "fasc" and "dpts" not in it],
             [it for it in items if it["kind"] == "apo"]]
    out = []
    for pool in pools:
        take = min(len(pool), n // 3)
        out += [pool[i] for i in rng.choice(len(pool), take, replace=False)]
    return out


def load_v1_init(model, fold: int, torch) -> str:
    """Optional warm start from the fasc_orient_v1 checkpoint of the SAME fold (same fascicle folds)."""
    hits = [p for p in Path("/kaggle/input").rglob(f"fold{fold}.pt") if "checkpoints" in p.parts]
    if not hits:
        return "imagenet"
    try:
        sd = torch.load(hits[0], map_location="cpu", weights_only=False)["state_dict"]
        own = model.state_dict()
        n_copy = 0
        for k, v in sd.items():
            v = v.float() if v.is_floating_point() else v
            if k in own and own[k].shape == v.shape:
                own[k] = v
                n_copy += 1
            elif k in own and v.shape[0] == 3 and own[k].shape[0] == N_OUT:  # 3 -> 5 output channels
                own[k][:3] = v
                n_copy += 1
        model.load_state_dict(own)
        return f"v1:{hits[0]} ({n_copy}/{len(own)} tensors)"
    except Exception:  # noqa: BLE001
        log(f"warm start failed, using ImageNet:\n{traceback.format_exc()}")
        return "imagenet"


def train_fold(fold: int, gpu_state: dict, torch) -> None:
    from torch.utils.data import DataLoader

    rng = np.random.default_rng(SEED + fold)
    tr = [it for it in ITEMS if it["fold"] != fold]
    va = [it for it in ITEMS if it["fold"] == fold]
    if SMOKE:
        tr, va = _smoke_pick(tr, SMOKE_TRAIN, rng), _smoke_pick(va, 12, rng)
    torch.manual_seed(SEED + fold)
    n_cpu = os.cpu_count() or 4
    n_workers = 2 if DEV == "cpu" else max(2, min(4, n_cpu // gpu_state["n_parallel"] + 1))
    ds = PairSet(tr, augment=True, repeat=1)
    if DEV == "cpu":
        n_workers = 0  # forked loader workers deadlock once the main process owns an intra-op thread pool
    wk = dict(persistent_workers=True, worker_init_fn=_worker_init, prefetch_factor=4) if n_workers else {}
    dl = DataLoader(ds, batch_size=BATCH_ITEMS, shuffle=True, num_workers=n_workers, pin_memory=DEV == "cuda",
                    drop_last=True, **wk)
    t_cache = time.time()
    cache = build_val_cache(va, torch)
    kinds = {k: sum(1 for it in tr if (it["kind"], "dpts" in it) == k) for k in (("fasc", True), ("fasc", False), ("apo", True))}
    log(f"fold {fold}: train={len(tr)} {kinds} val={len(va)} loader_workers={n_workers} steps/epoch={len(dl)} "
        f"val_cache={time.time() - t_cache:.1f}s device={DEV}")

    model = build_model(pretrained=True)
    init = load_v1_init(model, fold, torch)
    log(f"fold {fold}: init {init}")
    model = model.to(DEV).to(memory_format=torch.channels_last)
    enc_params = list(model.encoder.parameters())
    enc_ids = {id(p) for p in enc_params}
    dec_params = [p for p in model.parameters() if id(p) not in enc_ids]
    opt = torch.optim.AdamW([{"params": enc_params, "lr": LR_ENC}, {"params": dec_params, "lr": LR_DEC}],
                            weight_decay=WEIGHT_DECAY)
    steps = len(dl)
    warm = max(1, int(steps * WARMUP_EPOCHS))
    n_epochs = gpu_state.get("n_epochs", MAX_EPOCHS)
    if "ep_time" in gpu_state:
        folds_left = max(1, gpu_state["plan_folds"] - gpu_state["done"])
        n_fit = int((T0 + TRAIN_BUDGET_S - time.time()) / folds_left / (gpu_state["ep_time"] * 1.03))
        n_epochs = int(max(MIN_EPOCHS, min(n_epochs, n_fit)))
        log(f"fold {fold}: n_epochs={n_epochs} (budget fit {n_fit})")
    sched_state = {"total": n_epochs * steps}

    def lr_lambda(step: int) -> float:
        if step < warm:
            return 0.05 + 0.95 * step / warm
        total = max(sched_state["total"], warm + 1)
        prog = min(1.0, (step - warm) / (total - warm))
        return LR_FLOOR + (1 - LR_FLOOR) * 0.5 * (1 + math.cos(math.pi * prog))

    sched = torch.optim.lr_scheduler.LambdaLR(opt, lr_lambda)
    scaler = torch.amp.GradScaler("cuda", enabled=DEV == "cuda")
    hist_path = METRIC_DIR / f"history_fold{fold}.csv"
    mcols = ["dice50", "ang_mae", "fa_mae", "ln_mae", "pa_mae", "score"]
    with open(hist_path, "w", newline="") as fh:
        csv.writer(fh).writerow(["epoch", *LOSS_KEYS, *mcols, "lr", "sec"])
    best, best_epoch, nonfinite = None, 0, 0
    ckpt_path = CKPT_DIR / f"fold{fold}.pt"
    epoch = 0
    while epoch < n_epochs:
        epoch += 1
        model.train()
        t_ep = time.time()
        sums = np.zeros(len(LOSS_KEYS))
        nb = 0
        for step, b in enumerate(dl, 1):
            b = to_dev(b, torch)
            out = model_out(model, to_input(b["img"], torch), torch)
            ls = compute_losses(out, b, torch)
            if not bool(torch.isfinite(ls["loss"])):
                nonfinite += 1
                opt.zero_grad(set_to_none=True)
                log(f"fold {fold} ep {epoch} step {step}: non-finite loss, step skipped")
                continue
            opt.zero_grad(set_to_none=True)
            scaler.scale(ls["loss"]).backward()
            scaler.unscale_(opt)
            torch.nn.utils.clip_grad_norm_(model.parameters(), 2.0)
            scaler.step(opt)
            scaler.update()
            sched.step()
            sums += [float(ls[k]) for k in LOSS_KEYS]
            nb += 1
            if step % 50 == 0 or (SMOKE and step % 4 == 0):
                el = time.time() - t_ep
                log(f"fold {fold} ep {epoch} step {step}/{steps} " + " ".join(f"{k}={sums[i] / nb:.4f}" for i, k in enumerate(LOSS_KEYS))
                    + f" s/step={el / step:.2f}")
        ep_rows = [] if epoch in EARLY_EPOCHS else None  # staged readout: per-image val rows, no TTA
        met = evaluate(model, cache, torch, rows_out=ep_rows, items=va if ep_rows is not None else None)
        if ep_rows:
            with open(METRIC_DIR / f"early_fold{fold}_ep{epoch}.csv", "w", newline="") as fh:
                w = csv.writer(fh)
                w.writerow(OOF_COLS)
                w.writerows(ep_rows)
        sec = time.time() - t_ep
        lr_now = opt.param_groups[0]["lr"]
        sums /= max(1, nb)
        log(f"EPOCH fold={fold} ep={epoch}/{n_epochs} " + " ".join(f"{k}={sums[i]:.4f}" for i, k in enumerate(LOSS_KEYS))
            + " | val " + " ".join(f"{k}={met[k]:.3f}" for k in mcols) + f" | lr={lr_now:.2e} total={sec:.0f}s")
        with open(hist_path, "a", newline="") as fh:
            csv.writer(fh).writerow([epoch, *[round(float(v), 5) for v in sums], *[met[k] for k in mcols], lr_now, sec])
        if best is None or met["score"] < best["score"]:
            best, best_epoch = met, epoch
            sd = {k: (v.half() if v.is_floating_point() else v) for k, v in model.state_dict().items()}
            bad = [k for k, v in model.state_dict().items() if v.is_floating_point() and not bool(torch.isfinite(v.half()).all())]
            if bad:
                log(f"fold {fold}: WARNING {len(bad)} tensors overflow in fp16, saving fp32 instead: {bad[:3]}")
                sd = dict(model.state_dict())
            torch.save({"state_dict": sd, "epoch": epoch, "metrics": met, "fold": fold, "encoder": ENCODER,
                        "size": SIZE, "classes": CHANNELS}, ckpt_path)
            log(f"fold {fold}: saved best epoch {epoch} score={met['score']:.3f}")
        if epoch == 1 and "n_epochs" not in gpu_state and not SMOKE:
            ep_time = sec
            left = T0 + TRAIN_BUDGET_S - time.time() + ep_time
            n_epochs = int(max(MIN_EPOCHS, min(MAX_EPOCHS, (left / gpu_state["plan_folds"]) // (ep_time * 1.03))))
            gpu_state["n_epochs"], gpu_state["ep_time"] = n_epochs, ep_time
            sched_state["total"] = n_epochs * steps
            log(f"fold {fold}: epoch time {ep_time:.0f}s -> n_epochs={n_epochs} for all folds on this device")
        if time.time() > T0 + HARD_TRAIN_END_S:
            log(f"fold {fold}: HARD time limit reached after epoch {epoch}; stopping this fold")
            break
    del dl
    state = torch.load(ckpt_path, map_location=DEV, weights_only=False)
    model.load_state_dict({k: v.float() if v.is_floating_point() else v for k, v in state["state_dict"].items()})
    rows: list = []
    met_tta = evaluate(model, cache, torch, tta=True, rows_out=rows, items=va)
    log(f"fold {fold}: best epoch {best_epoch}; TTA val " + json.dumps(met_tta))
    with open(METRIC_DIR / f"oof_readout_fold{fold}.csv", "w", newline="") as fh:
        w = csv.writer(fh)
        w.writerow(OOF_COLS)
        w.writerows(rows)
    res = {"fold": fold, "best_epoch": best_epoch, "n_epochs": n_epochs, "best": best, "tta": met_tta, "init": init,
           "n_train": len(tr), "n_val": len(va), "nonfinite_steps": nonfinite}
    (METRIC_DIR / f"fold{fold}.json").write_text(json.dumps(res, indent=2))
    del model, opt, cache
    if DEV == "cuda":
        torch.cuda.empty_cache()


def gpu_worker(gpu: int, folds: list[int], plan_folds: int, n_parallel: int) -> None:
    global _LOG_PREFIX, _LOG_FILE, DEV
    os.environ["CUDA_VISIBLE_DEVICES"] = str(gpu)
    _LOG_PREFIX = f"[gpu{gpu}]"
    _LOG_FILE = LOG_DIR / f"gpu{gpu}.log"
    code = 0
    try:
        import torch

        DEV = "cuda"
        torch.backends.cudnn.benchmark = True
        torch.set_num_threads(1)
        cv2.setNumThreads(1)
        log(f"worker start folds={folds} device={torch.cuda.get_device_name(0)}")
        state = {"plan_folds": plan_folds, "n_parallel": n_parallel, "done": 0}
        for k in folds:
            try:
                train_fold(k, state, torch)
            except Exception:  # noqa: BLE001
                code = 1
                log(f"fold {k} FAILED:\n{traceback.format_exc()}")
                torch.cuda.empty_cache()
            state["done"] += 1
    except BaseException:  # noqa: BLE001
        code = 2
        log(f"worker FAILED:\n{traceback.format_exc()}")
    os._exit(code)


# =============================================================================================
# v33 overlay, part C: self-checks, inference, main
# =============================================================================================
def self_checks(torch) -> dict:
    """Readout and angle-transport checks on synthetic maps (no data, no model)."""
    res = {}
    hh = ww = 256
    ys, xs = torch.meshgrid(torch.arange(hh, dtype=torch.float32), torch.arange(ww, dtype=torch.float32), indexing="ij")
    worst_f = worst_l = 0.0
    for th_deg, ln_deg in ((-20.0, 3.0), (-8.0, -6.0), (-35.0, 10.0), (15.0, 0.0)):
        th, ph = math.radians(th_deg), math.radians(ln_deg)
        cp = torch.full((1, hh, ww), math.cos(2 * th))
        sp = torch.full((1, hh, ww), math.sin(2 * th))
        dist = ((ys - 180.0) * math.cos(ph) - (xs - 128.0) * math.sin(ph)).abs()
        ed = (torch.exp(-0.5 * (dist / 1.5) ** 2) * 0.95 + 0.01).unsqueeze(0)
        f, l, _, _ = readout(cp, sp, torch.rand(1, hh, ww), ed, torch.ones(1, hh, ww), torch)
        worst_f = max(worst_f, _deg(float(f) - th))
        worst_l = max(worst_l, _deg(float(l) - ph))
    res["readout_fasc_err_deg"], res["readout_line_err_deg"] = worst_f, worst_l
    rng = np.random.default_rng(0)
    worst_t = 0.0
    for _ in range(50):
        la, lb = aug_matrix(rng)[:2, :2], aug_matrix(rng)[:2, :2]
        th = rng.uniform(-1.2, 1.2)
        d0 = np.linalg.inv(la) @ np.array([math.cos(th), math.sin(th)])
        d1 = lb @ d0
        got = float(map_angle(torch.tensor([th], dtype=torch.float32), torch.tensor(la[None], dtype=torch.float32),
                              torch.tensor(lb[None], dtype=torch.float32), torch))
        worst_t = max(worst_t, _deg(got - math.atan2(d1[1], d1[0])))
    res["transport_err_deg"] = worst_t
    # sample-level check: the label of view B equals the transported label of view A for one straight fragment
    it = {"kind": "fasc", "crop": np.full((300, 400), 90, np.uint8), "segs": np.array([[60, 220, 330, 120]], np.float32),
          "dpts": np.stack([np.arange(20, 380, 4.0), 250 + 0.05 * np.arange(20, 380, 4.0)], 1).astype(np.float32)}
    worst_s = worst_sl = 0.0
    for seed in range(30):
        r = np.random.default_rng(seed)
        a, b = make_sample(it, r), make_sample(it, r)
        la, lb = torch.tensor(a["lin"][None]), torch.tensor(b["lin"][None])
        if a["hf"] and b["hf"]:
            worst_s = max(worst_s, _deg(float(map_angle(torch.tensor([float(a["tf"])]), la, lb, torch)) - float(b["tf"])))
        if a["ha"] and b["ha"]:
            worst_sl = max(worst_sl, _deg(float(map_angle(torch.tensor([float(a["tl"])]), la, lb, torch)) - float(b["tl"])))
    res["sample_fasc_transport_err_deg"], res["sample_line_transport_err_deg"] = worst_s, worst_sl
    res["pass"] = bool(worst_f < 0.2 and worst_l < 0.3 and worst_t < 0.01 and worst_s < 0.05 and worst_sl < 0.3)
    return res


def predict_native(models, gray: np.ndarray, box, torch):
    """Fold-mean + hflip TTA maps at native resolution (uint8) and the readout of the mean maps."""
    x1, y1, x2, y2 = box
    crop = gray[y1:y2, x1:x2]
    inp, m = make_input(crop)
    x = to_input(torch.from_numpy(inp[None]).to(DEV), torch)
    acc = None
    with torch.no_grad():
        for model in models:
            cur = torch.stack([t[0] for t in forward_maps(model, x, torch, True)], -1)
            acc = cur if acc is None else acc + cur
        acc = acc / len(models)
        valid = torch.from_numpy(_poly_mask(m, x2 - x1, y2 - y1)[None]).to(DEV).float()
        f, l, ws, qs = readout(acc[None, ..., 1], acc[None, ..., 2], acc[None, ..., 4], acc[None, ..., 3], valid, torch)
    maps = acc.cpu().numpy().astype(np.float32)
    back = unletterbox(maps, m, x2 - x1, y2 - y1)
    full = np.zeros((gray.shape[0], gray.shape[1], N_OUT), np.float32)
    full[y1:y2, x1:x2] = back
    enc = encode_channels(full[..., 0], full[..., 1], full[..., 2])
    enc["deep"] = np.clip(np.round(full[..., 3] * 255.0), 0, 255).astype(np.uint8)
    enc["wread"] = np.clip(np.round(full[..., 4] * 255.0), 0, 255).astype(np.uint8)
    fd, ld = math.degrees(float(f)), math.degrees(float(l))
    pa = math.degrees(float(wrap_half(l - f, torch)))
    return enc, [round(fd, 4), round(ld, 4), round(pa, 4), round(float(ws), 2), round(float(qs), 2)]


def main() -> None:
    global ITEMS, _LOG_FILE, DEV
    for d in (MASKBANK, CKPT_DIR, LOG_DIR, METRIC_DIR, VIZ_DIR, TMP / "ext"):
        d.mkdir(parents=True, exist_ok=True)
    _LOG_FILE = LOG_DIR / "main.log"
    log(f"MODE={MODE} python={sys.version.split()[0]} cpu={os.cpu_count()}")
    log("nvidia-smi: " + sh("nvidia-smi -L").strip().replace("\n", " | "))
    import torch

    torch.set_num_threads(1)
    smp = ensure_smp()
    import timm

    log(f"torch={torch.__version__} smp={smp.__version__} timm={timm.__version__} cv2={cv2.__version__}")
    checks = self_checks(torch)
    (METRIC_DIR / "selfcheck.json").write_text(json.dumps(checks, indent=2))
    log("self checks: " + json.dumps(checks))
    if not checks["pass"]:
        raise RuntimeError("readout self checks failed")

    test_dir = find_dir("test_set_v2")
    pairs = find_pairs(find_dir("fasc_images_new_model_v1"), find_dir("fasc_masks_new_model_v1"))
    fasc_items, alias_rows, stats = prepare_items(pairs)  # folds identical to fasc_orient_v1
    for it in fasc_items:
        it["kind"] = "fasc"
    apo_pairs = find_apo_pairs()
    t = time.time()
    ctx = mp.get_context("fork")
    with ctx.Pool(min(4, os.cpu_count() or 2)) as pool:
        apo_all = list(pool.imap(prep_apo, apo_pairs, chunksize=8))
    seen, apo_items = set(), []
    for r in sorted(apo_all, key=lambda r: r["stem"]):
        if r["empty"] or r["ih"] in seen:
            continue
        seen.add(r["ih"])
        apo_items.append(r)
    stats["apo_pairs"], stats["apo_items"] = len(apo_pairs), len(apo_items)
    log(f"aponeurosis: {len(apo_pairs)} pairs -> {len(apo_items)} items with a deep edge in {time.time() - t:.0f}s")
    stats["both_mask"] = attach_pairs(fasc_items, apo_items, {Path(p).stem: p for p, _ in pairs})
    stats["apo_folds"] = assign_apo_folds(fasc_items, apo_items)
    for it in apo_items:
        del it["dpts_full"]
    ITEMS = fasc_items + apo_items
    stats["fold_table"] = {f"{k}{'+deep' if d else ''}": [sum(1 for it in ITEMS if it["fold"] == f and it["kind"] == k
                                                              and ("dpts" in it) == d) for f in range(N_FOLDS)]
                           for k, d in (("fasc", True), ("fasc", False), ("apo", True))}
    log("data stats: " + json.dumps(stats))
    with open(METRIC_DIR / "folds.csv", "w", newline="") as fh:
        w = csv.writer(fh)
        w.writerow(["stem", "representative", "group", "fold"])
        w.writerows(alias_rows)
        w.writerows([[it["stem"], it["stem"], -1, it["fold"]] for it in apo_items])
    (METRIC_DIR / "data_stats.json").write_text(json.dumps(stats, indent=2, default=str))

    _m = build_model(pretrained=True)  # warm the weight cache before any fork
    n_params = sum(p.numel() for p in _m.parameters())
    del _m
    log(f"pretrained {ENCODER} cached ({n_params / 1e6:.1f}M params)")

    n_gpu = sh("nvidia-smi -L").count("GPU ")
    datasets: dict[str, list[tuple[str, Path, str]]] = {}
    test_files = sorted([p for p in test_dir.rglob("*") if p.suffix.lower() in IMAGE_SUFFIXES], key=lambda p: p.name)
    datasets["test"] = [(p.stem, p, p.name) for p in test_files][:TEST_LIMIT]
    extra_names = ("static",) if CPU_SMOKE else ("static", "dynamic", "vl")

    def fetch_extras():
        for name in extra_names:
            try:
                datasets[name] = gather_extra(name)
            except Exception:  # noqa: BLE001
                log(f"extra {name} failed:\n{traceback.format_exc()}")

    if n_gpu == 0:
        if not SMOKE:
            raise RuntimeError("full mode needs a GPU")
        DEV = "cpu"
        torch.set_num_threads(os.cpu_count() or 2)
        state = {"plan_folds": len(TRAIN_FOLDS), "n_parallel": 1, "done": 0}
        for k in TRAIN_FOLDS:
            train_fold(k, state, torch)
            state["done"] += 1
        fetch_extras()
    else:
        assign = [TRAIN_FOLDS[0::2], TRAIN_FOLDS[1::2]] if n_gpu >= 2 and len(TRAIN_FOLDS) > 1 else [TRAIN_FOLDS]
        plan = max(len(a) for a in assign)
        log(f"GPU fold assignment {assign} plan_folds={plan}")
        procs = []
        for g, folds in enumerate(assign):
            p = ctx.Process(target=gpu_worker, args=(g, folds, plan, len(assign)), daemon=False)
            p.start()
            procs.append(p)
            time.sleep(5)
        fetch_extras()
        while any(p.is_alive() for p in procs):
            time.sleep(30)
        for g, p in enumerate(procs):
            p.join()
            log(f"gpu worker {g} exit code {p.exitcode}")
        DEV = "cuda"

    # ---- summaries: per-fold metrics and the pooled out-of-fold readout table (gate G0 input)
    fold_res = [json.loads((METRIC_DIR / f"fold{f}.json").read_text()) for f in TRAIN_FOLDS
                if (METRIC_DIR / f"fold{f}.json").exists()]
    oof = []
    for f in TRAIN_FOLDS:
        fp = METRIC_DIR / f"oof_readout_fold{f}.csv"
        if fp.exists():
            with open(fp) as fh:
                oof += list(csv.DictReader(fh))
    with open(WORK / "oof_readout.csv", "w", newline="") as fh:
        w = csv.DictWriter(fh, fieldnames=OOF_COLS)
        w.writeheader()
        w.writerows(oof)

    def pooled(sel, fn):
        v = [fn(r) for r in oof if sel(r)]
        return {"n": len(v), "mae": float(np.mean(v)) if v else None}

    g = lambda r, k: math.radians(float(r[k]))  # noqa: E731
    summary = {
        "folds": fold_res,
        "oof_fasc_angle": pooled(lambda r: r["has_fasc"] == "1", lambda r: _deg(g(r, "pred_fasc_deg") - g(r, "gt_fasc_deg"))),
        "oof_deep_line": pooled(lambda r: r["has_deep"] == "1", lambda r: _deg(g(r, "pred_line_deg") - g(r, "gt_line_deg"))),
        "oof_pa_both_mask": pooled(lambda r: r["has_fasc"] == "1" and r["has_deep"] == "1",
                                   lambda r: _deg((g(r, "pred_line_deg") - g(r, "pred_fasc_deg"))
                                                  - (g(r, "gt_line_deg") - g(r, "gt_fasc_deg")))),
    }
    (METRIC_DIR / "cv_summary.json").write_text(json.dumps(summary, indent=2))
    log("CV summary: " + json.dumps({k: v for k, v in summary.items() if k != "folds"}))

    # ---- fold-mean + hflip TTA inference: maps and readout
    ckpts = sorted(CKPT_DIR.glob("fold*.pt"))
    if not ckpts:
        raise RuntimeError("no checkpoints were produced")
    models = []
    for cp in ckpts:
        m = build_model(pretrained=False)
        st = torch.load(cp, map_location="cpu", weights_only=False)
        m.load_state_dict({k: v.float() if v.is_floating_point() else v for k, v in st["state_dict"].items()})
        models.append(m.to(DEV).eval().to(memory_format=torch.channels_last))
    log(f"inference with {len(models)} fold models on {DEV}")
    manifest_rows, read_rows = [], []
    for name in ("test", *extra_names):
        entries = datasets.get(name) or []
        if not entries:
            continue
        t = time.time()
        writers = {ch: NpzZip(MASKBANK / f"{name}__{MODEL_NAME}_{ch}.npz") for ch in CHANNELS}
        n_ok = 0
        for j, (key, path, src) in enumerate(entries):
            try:
                gray = read_gray(path)
                if max(gray.shape) > 4000 or min(gray.shape) < 64:
                    continue
                box, kind = viewport(gray, path.suffix.lower())
                enc, rd = predict_native(models, gray, box, torch)
                for ch in CHANNELS:
                    writers[ch].add(key, enc[ch])
                manifest_rows.append([name, key, src, gray.shape[0], gray.shape[1]])
                read_rows.append([name, key, kind, *box, *rd])
                n_ok += 1
                if j < 3:
                    save_viz(VIZ_DIR / f"{name}_{key}.jpg", gray, enc)
            except Exception:  # noqa: BLE001
                log(f"inference failed {name}/{src}:\n{traceback.format_exc()}")
        for w in writers.values():
            w.close()
        log(f"inference {name}: {n_ok}/{len(entries)} images in {time.time() - t:.0f}s")
    with open(MASKBANK / "manifest.csv", "w", newline="") as fh:
        w = csv.writer(fh)
        w.writerow(["dataset", "image_id", "source_filename", "height", "width"])
        w.writerows(manifest_rows)
    with open(WORK / "readout.csv", "w", newline="") as fh:
        w = csv.writer(fh)
        w.writerow(["dataset", "image_id", "layout", "x1", "y1", "x2", "y2", "fasc_deg", "line_deg", "pa_image_deg",
                    "w_sum", "q_sum"])
        w.writerows(read_rows)
    config = {
        "model": MODEL_NAME, "mode": MODE, "encoder": ENCODER, "arch": "smp.Unet", "smp": smp.__version__,
        "torch": torch.__version__, "size": SIZE, "channels": list(CHANNELS),
        "angle_convention": "angles in image pixel coords of the file (x right, y down), undirected; "
                            "pa_image_deg = line_deg - fasc_deg, NOT corrected for pixel aspect",
        "readout": "fascicle = weighted doubled-angle mean (weights wread*valid); deep line = total least squares "
                   "with weights deep^2*valid",
        "loss_weights": {"deep": W_DEEP, "fa": W_FA, "ln": W_LN, "pa": W_PA, "cons": W_CONS},
        "train": {"batch_items": BATCH_ITEMS, "views": 2, "max_epochs": MAX_EPOCHS, "folds": TRAIN_FOLDS, "seed": SEED},
        "data_stats": stats, "selfcheck": checks, "elapsed_min": (time.time() - T0) / 60,
    }
    (WORK / f"{MODEL_NAME}_config.json").write_text(json.dumps(config, indent=2, default=str))
    shutil.rmtree(TMP, ignore_errors=True)
    log(f"DONE elapsed={(time.time() - T0) / 60:.1f} min")


if __name__ == "__main__":
    main()
